/* 折线拐角圆角化：顶点前后各退 r，用二次贝塞尔把尖角磨圆（环路不可能是硬直角） */

const ringLayer = el('g',{id:'ringLayer'}, base);
RINGS.forEach(R => {
  /* 实测几何本身已足够密，直接折线连接；被画布裁断的环按段拆开画 */
  R.s.forEach(seg => {
    const d = seg.map(([lng,lat], i) =>
        (i ? 'L' : 'M') + PX(lng).toFixed(1) + ' ' + PY(lat).toFixed(1)).join('')
      + (R.closed ? 'Z' : '');
    el('path', { d, fill:'none', stroke:'#b3c3d3',
      'stroke-width':R.lw, opacity:R.k, 'stroke-linejoin':'round',
      'stroke-linecap':'round', 'vector-effect':'non-scaling-stroke' }, ringLayer);
  });

  /* 环名压在环线上：用背景色描边（paint-order），线在字下自然断开，
     不额外留白也不产生偏移 —— 标签随缩放保持屏幕字号，锚点由脚本吸附到环上 */
  const g=el('g',{},ringLayer);
  const t=el('text',{x:PX(R.l[0]), y:PY(R.l[1])+3.4, fill:'#8fa0b3', 'font-size':10.5,
    'text-anchor':'middle', 'letter-spacing':1, 'paint-order':'stroke',
    stroke:'#0b0f15', 'stroke-width':3.2, 'stroke-linejoin':'round'}, g);
  t.textContent = R.n;
  zsAdd(g, PX(R.l[0]), PY(R.l[1]));
});

