/* ============================================================
   地铁线路与站点
   数据源：高德地铁图接口（已是 GCJ-02），已裁剪到画布范围
   ============================================================ */
const lineLayer = document.getElementById('metroLineLayer');
const stLayer   = document.getElementById('metroStLayer');

METRO.forEach(L => {
  L.s.forEach(seg => {
    const d = seg.map((p, i) => (i ? 'L' : 'M') + PX(p[0]).toFixed(1) + ' ' + PY(p[1]).toFixed(1)).join('');
    el('path', { d, fill:'none', stroke:L.c, 'stroke-width':1.7,
      'stroke-linecap':'round', 'stroke-linejoin':'round', opacity:.6,
      'vector-effect':'non-scaling-stroke' }, lineLayer);
  });
});

METRO_ST.forEach(([lng, lat, tr, lines]) => {
  const x = PX(lng), y = PY(lat);
  const g = el('g', {class:'mst'}, stLayer);
  if (tr) {
    // 换乘站：空心白圈，最醒目
    el('circle', { cx:x, cy:y, r:3, fill:'#0b0f15',
      stroke:'#e3eaf2', 'stroke-width':1.5 }, g);
  } else {
    // 普通站：实心小灰点，和餐厅点（大彩圈＋暗底）明显区分
    el('circle', { cx:x, cy:y, r:1.8, fill:'#7b8697', opacity:.9 }, g);
  }
  const tip = el('title', {}, g);
  tip.textContent = (tr ? '换乘站 · ' : '') + lines;
  zsAdd(g, x, y);   // 站点在缩放中保持恒定大小
});

